      () => reject(new Error("UI readiness timed out")),
      10000,
    );
    ui!.once("error", (error) => {
      clearTimeout(timer);
      reject(error);
    });
    ui!.once("exit", (code) => {
      clearTimeout(timer);
      reject(new Error(`UI exited before readiness (${code})`));
    });
