    size += buffer.length;
    if (size > 8*1024*1024){req.resume();throw new Error("invalid_request");}
    chunks.push(buffer);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString());
  } catch {
    throw new Error("invalid_request");
  }
