            principal,
            input.reviewId,
            input.host,
            input.sessionId,
            input.connectionId,
          ),
        );
        return;
      }
      if (req.method === "POST" && url.pathname === "/api/connections") {
        user();
        const input = z
          .object({
            host: z.enum(["codex", "claude"]),
            sessionId: z.string().min(1),
            connectionId: z.string().min(1),
            corroborated: z.boolean(),
